{
  "type": "object",
  "properties": {
    "type": {
      "const": "placeholder.alpha.scalar.function"
    },
    "name": {
      "type": "string",
      "description": "The name of the placeholder function."
    },
    "spec": {
      "type": "string",
      "description": "The specification of the placeholder function."
    },
    "input_schema": {
      "type": "object",
      "properties": {
        "type": {
          "const": "object"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "The description of the object input."
        },
        "properties": {
          "type": "object",
          "additionalProperties": {
            "$ref": "InputSchema"
          },
          "description": "The properties of the object input."
        },
        "required": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "description": "The required properties of the object input."
        }
      },
      "required": [
        "type",
        "properties"
      ],
      "description": "The input schema for the placeholder scalar function."
    },
    "skip": {
      "$ref": "Expression",
      "description": "An expression which evaluates to a boolean indicating whether to skip this task. Receives: `input`."
    },
    "input": {
      "$ref": "Expression",
      "description": "An expression which evaluates to the input for the placeholder scalar function. Receives: `input`."
    }
  },
  "required": [
    "type",
    "name",
    "spec",
    "input_schema",
    "input"
  ],
  "description": "A placeholder alpha scalar function task expression. Always outputs 0.5."
}

{
  "anyOf": [
    {
      "$ref": "ImageRichContentPart",
      "description": "An image rich content part."
    },
    {
      "$ref": "AudioRichContentPart",
      "description": "An audio rich content part."
    },
    {
      "$ref": "VideoRichContentPart",
      "description": "A video rich content part."
    },
    {
      "$ref": "FileRichContentPart",
      "description": "A file rich content part."
    },
    {
      "type": "object",
      "additionalProperties": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "array",
      "items": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "string"
    },
    {
      "type": "number"
    },
    {
      "type": "boolean"
    }
  ],
  "description": "A value provided as input to a function."
}

{
  "anyOf": [
    {
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string",
          "description": "A JMESPath expression."
        }
      },
      "required": [
        "$jmespath"
      ],
      "description": "A JMESPath expression which evaluates to a value."
    },
    {
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string",
          "description": "A Starlark expression."
        }
      },
      "required": [
        "$starlark"
      ],
      "description": "A Starlark expression which evaluates to a value."
    },
    {
      "type": "object",
      "properties": {
        "$special": {
          "enum": [
            "input",
            "output",
            "l1_normalized_function_output",
            "input_items_output_length",
            "input_items_optional_context_split",
            "input_items_optional_context_merge",
            "vector_completion_scores",
            "vector_completion_scores_weighted_sum"
          ],
          "description": "A predefined special expression variant."
        }
      },
      "required": [
        "$special"
      ],
      "description": "A special predefined expression."
    }
  ],
  "description": "An expression (JMESPath, Starlark, or Special) which evaluates to a value."
}

{
  "anyOf": [
    {
      "$ref": "ImageRichContentPart",
      "description": "An image rich content part."
    },
    {
      "$ref": "AudioRichContentPart",
      "description": "An audio rich content part."
    },
    {
      "$ref": "VideoRichContentPart",
      "description": "A video rich content part."
    },
    {
      "$ref": "FileRichContentPart",
      "description": "A file rich content part."
    },
    {
      "type": "object",
      "additionalProperties": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "array",
      "items": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "string"
    },
    {
      "type": "number"
    },
    {
      "type": "boolean"
    }
  ],
  "description": "A value provided as input to a function."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "input_audio"
    },
    "input_audio": {
      "type": "object",
      "properties": {
        "data": {
          "type": "string",
          "description": "Base64 encoded audio data."
        },
        "format": {
          "enum": [
            "wav",
            "mp3"
          ],
          "description": "The format of the encoded audio data."
        }
      },
      "required": [
        "data",
        "format"
      ],
      "description": "The audio data and its format."
    }
  },
  "required": [
    "type",
    "input_audio"
  ],
  "description": "An audio rich content part."
}

{
  "anyOf": [
    {
      "$ref": "ImageRichContentPart",
      "description": "An image rich content part."
    },
    {
      "$ref": "AudioRichContentPart",
      "description": "An audio rich content part."
    },
    {
      "$ref": "VideoRichContentPart",
      "description": "A video rich content part."
    },
    {
      "$ref": "FileRichContentPart",
      "description": "A file rich content part."
