    {
      "type": "object",
      "additionalProperties": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "array",
      "items": {
        "$ref": "InputValue"
      }
    },
    {
      "type": "string"
    },
    {
      "type": "number"
    },
    {
      "type": "boolean"
    }
  ],
  "description": "A value provided as input to a function."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "image_url"
    },
    "image_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Either a URL of the image or the base64 encoded image data."
        },
        "detail": {
          "anyOf": [
            {
              "enum": [
                "auto",
                "low",
                "high"
              ],
              "description": "Specifies the detail level of the image."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "url"
      ],
      "description": "The URL of the image and its optional detail level."
    }
  },
  "required": [
    "type",
    "image_url"
  ],
  "description": "An image rich content part."
}

{
  "type": "object",
  "properties": {
    "type": {
      "enum": [
        "video_url",
        "input_video"
      ]
    },
    "video_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "URL of the video."
        }
      },
      "required": [
        "url"
      ]
    }
  },
  "required": [
    "type",
    "video_url"
  ],
  "description": "A video rich content part."
}
